package dr

// Third-party independent witness quorum arbitrator in Equinix Metal
type MultiCloudWitness struct {
    awsHealth bool
    gcpHealth bool
}

func (w *MultiCloudWitness) DecidePrimary(awsOk, gcpOk bool) string {
    if awsOk { return "AWS" }
    if gcpOk { return "GCP" }
    return "SPLIT_BRAIN_HALT"
}
